class TextExtractor\(HTMLParser\):
    def __init__\(self\):
        super\(\).__init__\(\)
        self.text_parts = []
        self._skip = False
        self._depth = 0
    def handle_starttag\(self, tag, attrs\):
        if tag in \('style', 'script'\):
            self._skip = True
            self._depth += 1
    def handle_endtag\(self, tag\):
        if tag in \('style', 'script'\):
            self._depth -= 1
            if self._depth <= 0:
                self._skip = False
                self._depth = 0
    def handle_data\(self, data\):
        if not self._skip:
            self.text_parts.append\(data\)
    def get_text\(self\):
        return ' '.join\(self.text_parts\)

